  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is manufacturing robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of demonstrations and sensor data that train robots to assemble, pick, tend machines, and inspect parts on real production lines, including force, part variation, and defect examples."
        }
      },
      {
        "@type": "Question",
        "name": "Why do factory robots need training data if they can be programmed?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Programming works for repeatable tasks. Tasks with high variation, such as flexible parts, cable routing, mixed kitting, and cosmetic inspection, are easier to learn from demonstrations and data than to hand-code."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data without stopping our production line?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Sessions are scheduled around shifts and changeovers, and capture rigs are designed so they don't add downtime to the cell."
        }
      },
      {
        "@type": "Question",
        "name": "How do you get enough defect examples for inspection models?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We source defects from quality holds and scrap, stage safe variants, and capture them under the same lighting and angles as production, tagging each by defect type."
        }
      },
      {
        "@type": "Question",
        "name": "Do you record force data for assembly tasks?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Contact-rich demonstrations include wrist force-torque and, where useful, tactile and audio streams on a shared clock."
        }
      },
      {
        "@type": "Question",
        "name": "Can you support humanoids working on factory lines?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We run real-robot teleoperation and egocentric capture of line tasks for humanoid teams; see our humanoid industry page for details."
        }
      }
    ]
  }
]
